pub(super) fn test_aarch64_neon_vpaddd_u64_normal2() -> Result<(), String> {
    unsafe {
        let result = vpaddd_u64(create_uint64x2_t_from([0, 18446744073709551615]));
        check_int_equality(result as i32, -1).map_err(|e| format!("{e} | call: vpaddd_u64(create_uint64x2_t_from([0, 18446744073709551615]))"))?;

        let total_iters = crate::cpu::get_iterations();
        if crate::get_fuzzing() && total_iters > 0 {
            log::info!("Starting fuzzing");
            for i in 0..total_iters {
                if i % 1000 == 0 && crate::cpu::should_stop() {
                    log::info!("Fuzzing stopped at iteration {}", i);
                    break;
                }
                let _ = vpaddd_u64(create_random_uint64x2_t());
            }
        }
    }
    Ok(())
}

